      const filename = get(file, 'filename') ?? '';
      if (typeof filename !== 'string' || !isInside(realPath(filename, cwd), root) ||
          path.normalize(filename).split(path.sep).some(part => part === 'vendor' || part === '.cargo')) continue;
      sourceFiles++;
